/* Nature Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="nature-light"] {
  --background: rgb(249, 245, 238);
  --foreground: rgb(64, 38, 34);
  --card: rgb(249, 245, 238);
  --card-foreground: rgb(64, 38, 34);
  --popover: rgb(249, 245, 238);
  --popover-foreground: rgb(64, 38, 34);
  --primary: rgb(48, 123, 52);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(233, 246, 234);
  --secondary-foreground: rgb(25, 96, 31);
  --muted: rgb(239, 234, 228);
  --muted-foreground: rgb(110, 76, 65);
  --accent: rgb(202, 232, 203);
  --accent-foreground: rgb(25, 96, 31);
  --destructive: rgb(197, 44, 42);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(224, 214, 201);
  --input: rgb(224, 214, 201);
  --ring: rgb(48, 123, 52);
  --chart-1: rgb(77, 174, 80);
  --chart-2: rgb(61, 143, 64);
  --chart-3: rgb(48, 123, 52);
  --chart-4: rgb(25, 96, 31);
  --chart-5: rgb(9, 33, 11);
  --radius: 0.5rem;
  --sidebar: rgb(239, 234, 228);
  --sidebar-foreground: rgb(64, 38, 34);
  --sidebar-primary: rgb(48, 123, 52);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(202, 232, 203);
  --sidebar-accent-foreground: rgb(25, 96, 31);
  --sidebar-border: rgb(224, 214, 201);
  --sidebar-ring: rgb(48, 123, 52);
  --font-sans: Montserrat, sans-serif;
  --font-serif: Merriweather, serif;
  --font-mono: Source Code Pro, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

