  --secondary-foreground: rgb(215, 226, 214);
  --muted: rgb(43, 58, 44);
  --muted-foreground: rgb(217, 208, 195);
  --accent: rgb(61, 143, 64);
  --accent-foreground: rgb(239, 234, 228);
  --destructive: rgb(197, 44, 42);
  --destructive-foreground: rgb(239, 234, 228);
  --border: rgb(60, 73, 59);
  --input: rgb(60, 73, 59);
  --ring: rgb(77, 174, 80);
  --chart-1: rgb(129, 201, 132);
  --chart-2: rgb(103, 187, 107);
  --chart-3: rgb(77, 174, 80);
  --chart-4: rgb(70, 160, 74);
  --chart-5: rgb(61, 143, 64);
  --radius: 0.5rem;
  --sidebar: rgb(28, 43, 31);
  --sidebar-foreground: rgb(239, 234, 228);
  --sidebar-primary: rgb(77, 174, 80);
  --sidebar-primary-foreground: rgb(9, 33, 11);
  --sidebar-accent: rgb(61, 143, 64);
